import { useEffect, useId, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import './command-palette.css';

// Availability check: the supplied package guidance names DialogHeader and
// EmptyState, but does not expose a CommandPalette API. It supplies no complete
// catalog or signatures. This composition therefore does not claim that an
// exhaustive package search occurred or invent an import for CommandPalette.
// The unmatched combobox/listbox contract is local native markup.
export type Command = {id:string; label:string; group:string; run:()=>void};
type Props = {open:boolean; commands:Command[]; recentIds:string[]; onRecentChange:(ids:string[])=>void; onClose:()=>void};
export function CommandPalette({open, commands, recentIds, onRecentChange, onClose}:Props) {
  const root = useRef<HTMLDialogElement>(null), input = useRef<HTMLInputElement>(null);
  const title = useId(), summary = useId(), list = useId();
  const [query, setQuery] = useState('');
  const [activeId, setActiveId] = useState<string | null>(null);
  const matched = commands.filter(command => command.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  const recent = query.trim() ? [] : recentIds.map(id => matched.find(command => command.id === id)).filter((command):command is Command => !!command);
  const recentSet = new Set(recent.map(command => command.id));
  const groups = new Map<string,Command[]>();
  if (recent.length) groups.set('Recent commands', recent);
  for (const command of matched) {
    if (recentSet.has(command.id)) continue;
    const label = command.group || 'Commands';
    groups.set(label, [...(groups.get(label) ?? []), command]);
  }
  const ordered = [...groups.values()].flat();
  const activeIndex = Math.max(0, ordered.findIndex(command => command.id === activeId));
  const active = ordered[activeIndex];
  const optionId = (id:string) => list + '-' + encodeURIComponent(id);
  useEffect(() => {
    const element = root.current;
    if (!element) return;
    const previous = document.activeElement as HTMLElement | null;
    if (open) {setQuery(''); setActiveId(null); if (!element.open) element.showModal(); input.current?.focus();}
    else if (element.open) element.close();
    return () => { if (element.open) element.close(); if (previous?.isConnected) previous.focus(); };
  }, [open]);
  useEffect(() => {
    if (active) document.getElementById(optionId(active.id))?.scrollIntoView({block:'nearest'});
  }, [active?.id]);
  function execute(command:Command) {
    onRecentChange([command.id, ...recentIds.filter(id => id !== command.id)].slice(0,10));
    onClose();
    command.run();
  }
  return <dialog ref={root} className="kui-layout command-palette" aria-labelledby={title} aria-describedby={summary} onCancel={event => {event.preventDefault(); onClose();}}>
    <DialogHeader><h2 id={title}>Commands</h2><p id={summary}>Find a command. Use Up and Down to navigate, Enter to run, or Escape to close.</p></DialogHeader>
    <label htmlFor={list + '-search'}>Search commands</label>
    <input ref={input} id={list + '-search'} role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls={list} aria-activedescendant={active ? optionId(active.id) : undefined} value={query} onChange={event => {setQuery(event.target.value); setActiveId(null);}} onKeyDown={event => {
      if (event.nativeEvent.isComposing) return;
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault();
        if (ordered.length) setActiveId(ordered[(activeIndex + (event.key === 'ArrowDown' ? 1 : -1) + ordered.length) % ordered.length].id);
      } else if (event.key === 'Enter' && active) {event.preventDefault(); execute(active);}
    }}/>
    <div role="listbox" id={list} aria-label="Matching commands">
      {[...groups.entries()].map(([group, entries], groupIndex) => <div role="group" aria-labelledby={list + '-group-' + groupIndex} key={group}>
        <div id={list + '-group-' + groupIndex}>{group}</div>
        {entries.map(command => <div role="option" aria-selected={active?.id === command.id} id={optionId(command.id)} key={command.id} className="command-option" onMouseDown={event => event.preventDefault()} onClick={() => execute(command)}>
          {active?.id === command.id && <span aria-hidden="true">› </span>}{command.label}
        </div>)}
      </div>)}
    </div>
    {!ordered.length && <EmptyState><p>No matching commands. Try another search.</p></EmptyState>}
    <p role="status" aria-live="polite">{ordered.length} commands available</p>
    <button type="button" onClick={onClose}>Close</button>
  </dialog>;
}
// The application owns command permissions, execution and persisted recentIds.

