.command-palette { box-sizing: border-box; inline-size: min(36rem, calc(100% - 2rem)); max-block-size: calc(100dvh - 2rem); overflow: auto; overflow-wrap: anywhere; }
.command-palette::backdrop { background: rgb(0 0 0 / 45%); }
.command-palette input { inline-size: 100%; box-sizing: border-box; min-block-size: 44px; }
.command-option { min-block-size: 44px; display: flex; align-items: center; cursor: pointer; }
.command-option[aria-selected="true"] { outline: 2px solid currentColor; outline-offset: -2px; font-weight: bold; }
.command-palette :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
